COMBOS=[]
def add(key,title,ids,colors,power,practical,mana,ready,steps,result,risk,tip,source=None,family=None):
    COMBOS.append(dict(id=key,title=title,cards=[f'fra-{n}' if isinstance(n,int) else n for n in ids],colors=colors,power=power,practical=practical,mana=mana,ready=ready,steps=[dict(action=a,state=s) for a,s in steps],result=result,risk=risk,tip=tip,source=source,family=family or key))

