def enrich(cards):
    byid={c['id']:c for c in cards}
    for combo in COMBOS:
        assert 2<=len(combo['cards'])<=4
        assert all(i in byid for i in combo['cards']),combo['id']
        combo['commonOnly']=all(byid[i]['rarity']=='common' for i in combo['cards'])
        combo['noRare']=all(byid[i]['rarity'] in ('common','uncommon') for i in combo['cards'])
        combo['access']='Solo comuni' if combo['commonOnly'] else 'Comuni / non comuni' if combo['noRare'] else 'Richiede SPG' if any(i.startswith('spg') for i in combo['cards']) else 'Richiede rara'
    for c in cards:
        found=[x for x in COMBOS if c['id'] in x['cards']]
        families={}
        for x in found:
            q=.65*x['practical']+.35*x['power']
            families[x['family']]=max(q,families.get(x['family'],0))
        scores=sorted(families.values(),reverse=True)
        score=min(5,scores[0]+min(.5,.2*sum(max(0,x-2) for x in scores[1:4]))) if scores else None
        c.update(combos=[x['id'] for x in found],comboFamilies=len(families),comboScore=int(score*2+.5)/2 if score is not None else None)
    return COMBOS
